145	// fit truncates the text to the column and pads it out, emitting no escape
146	// sequence of its own — the caller styles what comes back. Doing it in that
147	// order is the whole point of this file: runewidth counts an escape sequence's
148	// bytes as width, so text has to be measured while it is still plain.
149	func fit(text string, width int, head bool) string {
150		cut := runewidth.Truncate(text, width, truncationMarker)
151		if head {
152			cut = truncateHead(text, width)
153		}
154		return lipgloss.NewStyle().Width(width).MaxWidth(width).Inline(true).Render(cut)
155	}
