// headerLine renders the column titles, sort arrow included.
func (m *Model[T]) headerLine(cols []table.Column) string {
	var line strings.Builder
	for _, col := range cols {
		if col.Width <= 0 {
			continue
		}
		// A header is cut at its end whatever the column asks for its values: a
		// title is recognised by how it starts, and TruncateHead is a statement
		// about the data.
		line.WriteString(m.styles.Header.Render(fit(col.Title, col.Width, false)))
	}
	return line.String()
}

// rowLine renders one row.
//
// A busy row shows the spinner in its status column instead of that column's
// own cell — on the selected row too. The glyph is the primary signal, and a
// signal that disappears under the cursor is one the user loses exactly when
// they are looking at it.
func (m *Model[T]) rowLine(cols []table.Column, item T, selected bool) string {
	_, busy := m.busyLabel(item)

	var line strings.Builder
	for i, c := range m.cfg.Columns {
		if i >= len(cols) || cols[i].Width <= 0 {
			continue
		}
		text := c.Cell(item)
		if busy && i == m.cfg.StatusColumn {
			text = m.spinnerFrame
		}
		fitted := fit(text, cols[i].Width, c.TruncateHead)
		if !busy && (!selected || m.preserveColumnColors) {
			if runs, ok := m.multiRunCell(c, item, fitted, selected); ok {
				line.WriteString(runs)
				continue
			}
		}
		line.WriteString(m.cellStyle(c, item, selected, busy, i).Render(fitted))
	}
	if selected {
		return m.styles.Selected.Render(line.String())
	}
	return line.String()
}

// fit truncates the text to the column and pads it out, emitting no escape
// sequence of its own — the caller styles what comes back. Doing it in that
// order is the whole point of this file: runewidth counts an escape sequence's
// bytes as width, so text has to be measured while it is still plain.
func fit(text string, width int, head bool) string {
	cut := runewidth.Truncate(text, width, truncationMarker)
	if head {
		cut = truncateHead(text, width)
	}
	return lipgloss.NewStyle().Width(width).MaxWidth(width).Inline(true).Render(cut)
}

// truncateHead keeps the *end* of the text, for the columns that declare it
// (Column.TruncateHead).
//
// A column of URLs, image references or paths shares its prefix on every row,
// so cutting the tail renders three identical cells that identify nothing —
// and it does so precisely when the column is squeezed to its floor, which is
// when it is hardest to read. Keeping the end is what tells the rows apart.
//
// runewidth rather than runes throughout: a cell is measured in terminal cells,
// and a CJK name counts two per rune.
func truncateHead(text string, width int) string {
	total := runewidth.StringWidth(text)
	if total <= width || width <= 0 {
		return text
	}
	marker := runewidth.StringWidth(truncationMarker)
	if width <= marker {
		// No room for the marker and anything after it. Saying "there is more"
		// with no idea what beats a single arbitrary character.
		return runewidth.Truncate(truncationMarker, width, "")
	}
	return runewidth.TruncateLeft(text, total-(width-marker), truncationMarker)
}

// cellStyle is the style one cell is rendered with.
//
// A row a view has coloured whole — error, busy, a CVE severity, via
// SelectedStyles or the busy override — drops every column's own colour and
// is handed to styles.Selected instead: a colour inside it would close with a
// reset that takes that solid background with it for the rest of the line.
// The highlight there answers "what state is this row in", and no per-cell
// colour is worth losing it to.
//
// **The plain "normal" selection is the opposite case** (§3.72 in the
// backlog, m.preserveColumnColors): each cell keeps its own colour and
// additionally repaints ColorTableLineSelected and bold **itself**, rather than
// once on an outer wrap. That is what makes it safe rather than a return of
// the defect above — every cell's own reset only ever uncovers the *same*
// background the next cell immediately repaints, so nothing but that
// background is ever exposed between two cells. styles.Selected still wraps
// the joined line afterward (rowLine), painting the same background again;
// by then it is redundant colour, not load-bearing, and it is what still
// pads the row out to the full content width.
//
// Off the selected row every cell carries an explicit foreground **and**
// background, whether or not the column asked for either. Both halves are
// forced for the same reason and each fixes its own defect:
//
//   - Background: lipgloss does not inherit one (Rule 115), and the app's
//     viewport style only reaches the cells that emit nothing of their own. One
//     coloured cell would otherwise end its line with a reset and strip the
//     background from everything to its right.
//   - Foreground: neither theme.DefaultTableStyles() nor bubbles' own sets one
//     on Cell, so a column that declares no Style rendered in whatever
//     foreground the terminal happens to use — the theme had no say. Four views
//     had written `Foreground(theme.ColorText)` into a Style of their own to get
//     it back, which is the shape a missing default takes.
//
// The busy row, for its part, does not consult `Style` either: what it says
// is that an operation is in progress, and a color by severity or by state
// on top of that would say the opposite. The spinner's glyph keeps
// `ColorHighlight`, the rest goes to `DimStyle` — the displayed state is in
// the process of ceasing to be true.
func (m *Model[T]) cellStyle(c Column[T], item T, selected, busy bool, at int) lipgloss.Style {
	if selected {
		if !m.preserveColumnColors {
			// Neither background nor text here: they would hide those of styles.Selected.
			return m.styles.Cell
		}
		style := m.styles.Cell
		if c.Style != nil {
			style = c.Style(item).Padding(0, 1)
		}
		if _, unset := style.GetForeground().(lipgloss.NoColor); unset {
			style = style.Foreground(theme.ColorText)
		}
		return style.Background(theme.ColorTableLineSelected).Bold(true)
	}
	if busy {
		style := theme.DimStyle
		if at == m.cfg.StatusColumn {
			style = lipgloss.NewStyle().Foreground(theme.ColorHighlight)
		}
		return style.Padding(0, 1).Background(theme.ColorBackground)
	}
	if c.Style == nil {
		return m.styles.Cell.Foreground(theme.ColorText).Background(theme.ColorBackground)
	}
	style := c.Style(item).Padding(0, 1)
	if _, unset := style.GetForeground().(lipgloss.NoColor); unset {
		style = style.Foreground(theme.ColorText)
	}
	if _, unset := style.GetBackground().(lipgloss.NoColor); unset {
		style = style.Background(theme.ColorBackground)
	}
	return style
}

// run is one coloured stretch of an already-fitted cell.
type run struct {
	text  string
	style lipgloss.Style
}

// multiRunCell renders a cell that colours more than one stretch of its text:
// Column.Spans when it answers a non-empty list, else Cut/TailStyle. ok is false
// for an ordinary one-run cell, which the caller renders through cellStyle.
func (m *Model[T]) multiRunCell(c Column[T], item T, fitted string, selected bool) (string, bool) {
	if c.Spans != nil {
		if spans := c.Spans(item); len(spans) > 0 {
			return m.renderRuns(m.spanRuns(c, item, spans, fitted, selected)), true
		}
		return "", false
	}
	if c.TailStyle == nil {
		return "", false
	}
	return m.splitCellRun(c, item, fitted, selected), true
}

// spanRuns lays spans over the fitted text from left to right: a negative width
// counts as 0, a zero-width span yields no run, what overflows the cell is cut
// and the cells left after the last span take c.Style. Widths are in runes, so
// like Cut they assume single-width glyphs.
func (m *Model[T]) spanRuns(c Column[T], item T, spans []Span, fitted string, selected bool) []run {
	runes := []rune(fitted)
	var runs []run
	pos := 0
	for _, s := range spans {
		end := min(pos+max(s.Width, 0), len(runes))
		if end > pos {
			runs = append(runs, run{string(runes[pos:end]), m.runStyle(s.Style, selected)})
			pos = end

	// CIGradeable is decided at load, not per frame: it needs the repository's
	// remote, which is a git call. An image is never gradeable — it has no
	// pipeline — so its zero value is already the truth.
	CIScore     *string
	CIGradeable bool
	// Misconfig is the misconfiguration verdict as the cache holds it, stored
	// rather than the finished state for Sensitive's reason: the verdict is one
	// calculation, in theme, and a row carrying it would be a second place able
	// to disagree with the workspaces list.
	Misconfig *scan.MisconfigSummary
	ScannedAt time.Time
	// Scanned is false between a ctrl+a purge and the scan that replaces it.
	// The target is still known — it is the counts that are not.
	Scanned  bool
	Scanning bool
	Failed   bool
	// Display is the image reference with its registry prefix replaced by the
	// configured alias, stamped by setInventory the way SpinnerFrame is — the
	// rows arrive from a Cmd, which cannot read the configuration off the model
	// (Rule 110), and a column function is built once and cannot either.
	//
	// Empty means nobody stamped it, and displayName falls back to Name: a row
	// built by hand must stay readable rather than render an empty cell.
	Display      string
	SpinnerFrame string
}

// inventoryColumnCritical is the column the inventory opens sorted by,
// descending: the target with the most critical findings is the one the view
// exists to surface.
//
// This is an index, so it follows the column order: Secrets slotted in
// between Target and CRIT. A stale value doesn't sort wrong, it doesn't sort
// at all anymore — `datatable` drops a direction that names no sortable
// column, and Secrets isn't one.
const inventoryColumnCritical = 3

// kindIcon is what the glyph column shows: which of the two caches the row came
// from. It is a column of its own rather than a prefix inside Target, the way
// the workspaces and containers tables do it — an icon glued into a text cell
// spends the identifying column's width on something that is not the name, and
// a column that measures the name has to measure the glyph too.
func (t scanTarget) kindIcon() string {
	if t.Kind == kindImage {
		return theme.IconDocker
	}
	return theme.IconWorkspace
}

// kindIconRole colours the glyph above. The repository shares the explorer's
// and the workspaces' role rather than declaring a third: the same object is
// listed by three views, and one colour for it is what a role is for.
func (t scanTarget) kindIconRole() theme.IconRole {
	if t.Kind == kindImage {
		return theme.IconRoleImage
	}
	return theme.IconRoleRepository
}

// shortName is what the Target column shows: the image reference with its
// registry prefix folded to the configured alias, or the repository path with
// the home directory folded back to "~". It is also what the title and the
// footer messages name the target.
//
// Both foldings answer the same pressure — this is the narrowest table in the
// application, and what a `nexus.example.com/docker-hosted/` prefix pushes out
// of the cell is the part that identifies the image. And both obey the same
// rule: the cache key stays the value everything else uses, so folding here
// cannot reach a loader, a scanner, or the directory a .gitleaksignore is
// written into.
func (t scanTarget) shortName() string {
	if t.Kind == kindRepo {
		return theme.FoldHome(t.Name)
	}
	if t.Display != "" {
		return t.Display
	}
	return t.Name
}

// secrets is the row's verdict. A row purged by ctrl+a no longer has a
// verdict either: its counters show `-`, and the icon says the same thing.
func (t scanTarget) secrets() theme.SecretsState {
	return theme.SecretsVerdict(t.Sensitive, t.Scanned)
}

// ci is the row's grade verdict, computed the way the workspaces list computes
// it — same function, same three absences. A purged row has no grade either:
// its counters print "-" and so does this column.
func (t scanTarget) ci() theme.CIScoreState {
	return theme.CIScoreVerdict(t.CIScore, t.Scanned, t.CIGradeable)
}

// misconfig is the row's misconfiguration verdict, computed the way the
// workspaces list and the images list compute theirs — same function, same
// three states. A purged row has looked at nothing: its counters print "-" and
// so does this column.
func (t scanTarget) misconfig() theme.MisconfigState {
	return theme.MisconfigVerdict(t.Misconfig != nil, t.Scanned, t.Misconfig.Total())
}

// labelFor names a target the way the table does, for the messages that have
// only a cache key to go on.
//
// It resolves the row rather than folding the string blind: an absolute
// repository path can legitimately begin with a configured registry URL, and
// only the row knows which of the two caches the name came from. A name with no
// row — nothing has been loaded yet — is returned untouched, which is worse
// than the alias but never wrong.
func (m Model) labelFor(name string) string {
	for _, t := range m.inventory.Items() {
		if t.Name == name {
			return t.shortName()
		}
	}
	return name
}

// labelForResult folds a result's target the same way, for the one caller that
// has no inventory to resolve against: a view constructed straight onto a
// stored result. The result carries its own TargetType, which is the same fact
// targetKind holds.
func labelForResult(cfg *config.Config, result *scan.Result) string {
	if result == nil {
		return ""
	}
	if result.TargetType != scan.TargetImage {
		return theme.FoldHome(result.Target)
	}
	return docker.ApplyAliases(result.Target, registryalias.From(cfg.Registry.Registries))
}

// countColumnWidth holds the four severity columns to one width. datatable
// already reserves room for the sort arrow, which would give CRIT and HIGH six
// cells and MED and LOW five — four adjacent columns of the same kind, ragged.
const countColumnWidth = 6

// countColumn builds one of the four severity columns. A purged row prints "-"
// rather than "0": nothing was found and nothing is known are different answers,
// and zero is the one a user reads as "clean".
//
// severity names the column's own level, for the colour. It is passed rather
// than derived from the title so that renaming a header cannot silently repaint
// a column — "CRIT" is an abbreviation, "CRITICAL" is the scanners' vocabulary.
func countColumn(title, severity string, get func(scan.SeverityCounts) int) datatable.Column[scanTarget] {
	return datatable.Column[scanTarget]{
		Title: title, Sizing: datatable.SizingFixed, MinWidth: countColumnWidth,
		Cell: func(t scanTarget) string {
			if !t.Scanned {
				return "-"
			}
			return strconv.Itoa(get(t.Counts))
		},
		// Only a count that found something is coloured. Four columns of
		// severity-coloured zeroes would be the whole table shouting at once,
		// which says no more than a table with no colour at all.
		Style: func(t scanTarget) lipgloss.Style {
			if !t.Scanned || get(t.Counts) == 0 {
				return theme.DimStyle
			}
			return theme.SeverityTextStyle(severity)
		},
		Less: func(a, b scanTarget) bool { return get(a.Counts) < get(b.Counts) },
	}
}

// inventoryScannedStyle colours the scan state: a failure is the one thing in
// this column worth interrupting for, and a target never scanned is dim rather
// than absent.
func inventoryScannedStyle(t scanTarget) lipgloss.Style {
	switch {
	case t.Failed:
		return theme.StatusErrorStyle
	case t.Scanning, !t.Scanned:
		return theme.DimStyle
	}
	// No opinion here: it's the table that sets the theme's text color.
	return lipgloss.NewStyle()
}

// inventoryScannedCell reports the scan state: the spinner while one runs, an
// error icon when the last attempt failed, otherwise how long ago it succeeded
// (Rule 127). Plain text throughout — Rule 122.
func inventoryScannedCell(t scanTarget) string {
	switch {
	case t.Scanning:
		return t.SpinnerFrame + "scanning"
	case t.Failed:
		return theme.IconError + " error"
	case t.Scanned:
		return theme.TimeAgo(t.ScannedAt)
	}
	return "-"
}

